using ABN=std::unique_ptr<BIGNUM,decltype(&BN_free)>;
using APoint=std::unique_ptr<EC_POINT,decltype(&EC_POINT_free)>;
ABN anumber(const std::string&s){BIGNUM*n=nullptr;require(BN_dec2bn(&n,s.c_str())>0,"group decimal");return ABN(n,BN_free);}
struct AGroup{
 std::unique_ptr<EC_GROUP,decltype(&EC_GROUP_free)> group{EC_GROUP_new_by_curve_name(NID_X9_62_prime192v1),EC_GROUP_free};
 std::unique_ptr<BN_CTX,decltype(&BN_CTX_free)> context{BN_CTX_new(),BN_CTX_free};
 std::vector<APoint> base;
 explicit AGroup(const Json&j){require(bool(group)&&bool(context),"named group allocation");auto n=anumber("0"),expected=anumber(sc_n.get_str());require(EC_GROUP_get_order(group.get(),n.get(),context.get())==1&&BN_cmp(n.get(),expected.get())==0,"exact subgroup coefficient order");for(const auto&q:j.arr){auto p=make();auto x=anumber(q.at("x").scalar),y=anumber(q.at("y").scalar);require(q.at("infinity").scalar=="false"&&EC_POINT_set_affine_coordinates(group.get(),p.get(),x.get(),y.get(),context.get())==1&&EC_POINT_is_on_curve(group.get(),p.get(),context.get())==1,"old group point incidence");base.push_back(std::move(p));}require(base.size()==225,"old group width");}
 APoint make()const{APoint p(EC_POINT_new(group.get()),EC_POINT_free);require(bool(p)&&EC_POINT_set_to_infinity(group.get(),p.get())==1,"point allocation");return p;}
 bool valid(const SCRow&row)const{require(row.size()==base.size(),"group row width");auto sum=make();for(size_t i=0;i<row.size();++i)if(row[i]!=0){SCBig v=row[i]<0?SCBig(-row[i]):row[i];auto n=anumber(v.get_str());auto term=make();require(EC_POINT_mul(group.get(),term.get(),nullptr,base[i].get(),n.get(),context.get())==1,"row scalar term");if(row[i]<0)require(EC_POINT_invert(group.get(),term.get(),context.get())==1,"signed row term");require(EC_POINT_add(group.get(),sum.get(),sum.get(),term.get(),context.get())==1,"row group addition");}return EC_POINT_is_at_infinity(group.get(),sum.get())==1;}
};
bool asame(const Json&a,const Json&b){if(a.kind!=b.kind||a.scalar!=b.scalar||a.arr.size()!=b.arr.size()||a.obj.size()!=b.obj.size())return false;for(size_t i=0;i<a.arr.size();++i)if(!asame(a.arr[i],b.arr[i]))return false;for(const auto&[k,v]:a.obj){auto p=b.obj.find(k);if(p==b.obj.end()||!asame(v,p->second))return false;}return true;}
template<class T>void areject(T action){bool bad=false;try{action();}catch(const std::exception&){bad=true;}require(bad,"audit corruption control accepted");}
void acode(const std::filesystem::path&p){std::ifstream in(p);std::string code;require(bool(in)&&bool(std::getline(in,code))&&code=="0","terminal native success receipt");}
void acoverage(const std::vector<std::array<int,2>>&parts,int n){int next=0;for(auto p:parts){require(p[0]==next&&p[1]==std::min(next+64,n),"complete ordered scan coverage");next=p[1];}require(next==n,"last scan block present");}
std::vector<size_t> abasis(const SCMat&a){std::map<size_t,SCRow> pivots;std::vector<size_t> selected;for(size_t i=0;i<a.size();++i){SCRow v=a[i];for(auto&x:v)x=sc_reduce(x);for(const auto&[p,row]:pivots){SCBig c=v[p];if(c!=0)for(size_t j=p;j<v.size();++j)v[j]=sc_reduce(v[j]-c*row[j]);}size_t p=0;while(p<v.size()&&v[p]==0)++p;if(p==v.size())continue;SCBig inverse;require(mpz_invert(inverse.get_mpz_t(),v[p].get_mpz_t(),sc_n.get_mpz_t())==1,"basis pivot inverse");for(size_t j=p;j<v.size();++j)v[j]=sc_reduce(v[j]*inverse);pivots.emplace(p,std::move(v));selected.push_back(i);}return selected;}
int main(int argc,char**argv){try{
 require(argc==4,"usage: audit_sections BASELINE TANGENTS SCAN_DIRECTORY");auto baseline=read_json(argv[1]),tangents=read_json(argv[2]);std::filesystem::path root=argv[3];acode(root/"exit-code.txt");auto first=read_json((root/"calls/batch-0/stdout.json").string());int n=first.at("pool_size").integer();require(n>=226&&n<=3000,"bounded complete pool");bool old_mode=first.at("old_mode").scalar=="true";const auto&points=first.at("points").arr;require(points.size()==size_t(n),"full point coordinates");
 for(size_t i=0;i<226;++i){const auto&q=baseline.at("pool").at("points").arr.at(i);require(q.at("x").scalar==points[i].at("x").scalar&&q.at("y").scalar==points[i].at("y").scalar,"old curve-pool prefix");require(asame(points[i].at("image"),baseline.at("images").arr.at(i).at("point")),"old elliptic image prefix");}
 SCMat old(6,SCRow(225));for(size_t i=0;i<6;++i)for(const auto&t:baseline.at("rows").arr.at(i).arr)old[i].at(size_t(t.arr[0].integer()))+=SCBig(t.arr[1].scalar);require(sc_rank(old)==6,"old baseline rank six");AGroup group(baseline.at("projected_base"));for(const auto&r:old)require(group.valid(r),"independent old elliptic row");
 auto full=sc_read_matrix(tangents.at("matrix"));require(full.size()==108,"frozen tangent rows");for(const auto&r:full)require(r.size()==429,"frozen tangent columns");SCMat aux;std::vector<int> owner_count(108);for(size_t j=225;j<429;++j){int owner=-1;for(size_t i=0;i<108;++i)if(sc_reduce(full[i][j])!=0){require(owner<0,"unshared old auxiliary");owner=int(i);}require(owner>=6,"old auxiliary owner");++owner_count[size_t(owner)];}for(size_t i=6;i<108;++i)require(owner_count[i]==2,"every added old row private");for(size_t i=0;i<108;++i){aux.emplace_back(full[i].begin()+225,full[i].end());if(i<6)for(size_t j=0;j<225;++j)require(sc_reduce(full[i][j])==sc_reduce(old[i][j]),"frozen baseline span binding");}size_t nrank=sc_rank(aux);require(nrank==102&&sc_rank(full)==108,"separate original full/new ranks");
 std::map<std::array<int,4>,Json> unique;std::vector<std::array<int,2>> coverage;size_t attempted=0;
 for(int start=0;start<n;start+=64){auto call=root/"calls"/("batch-"+std::to_string(start));acode(call/"exit-code.txt");auto data=read_json((call/"stdout.json").string());require(asame(data.at("points"),first.at("points"))&&data.at("old_mode").scalar==first.at("old_mode").scalar,"constant full point ordering across workers");coverage.push_back({data.at("start").integer(),data.at("end").integer()});require(coverage.back()[0]==start,"fixed expected batch identity");attempted+=size_t(data.at("lines_attempted").integer());for(const auto&s:data.at("sections").arr){require(s.at("support").arr.size()==4&&s.at("row").arr.size()==225,"complete section and row");std::array<int,4> ids{};for(size_t i=0;i<4;++i){ids[i]=s.at("support").arr[i].integer();require(ids[i]>=0&&ids[i]<n&&(i==0||ids[i-1]<=ids[i]),"ordered complete support");}int origin=s.at("origin").integer();require(origin>=start&&origin<std::min(start+64,n)&&std::find(ids.begin(),ids.end(),origin)!=ids.end(),"assigned section origin");auto [it,added]=unique.emplace(ids,s);if(!added)for(size_t j=0;j<225;++j)require(sc_reduce(SCBig(it->second.at("row").arr[j].scalar))==sc_reduce(SCBig(s.at("row").arr[j].scalar)),"duplicate complete divisor gives identical row");}}
 acoverage(coverage,n);auto missing=coverage;missing.erase(missing.begin());areject([&]{acoverage(missing,n);});require(attempted==size_t(n)*size_t(n+1)/2,"all pair lines and tangents attempted");require(unique.size()<=4096,"complete accepted-section bound");
 SCMat closed=old;std::vector<Json> sections;const auto&ref=baseline.at("pool").at("split_fibers").arr[0].at("point_indices").arr;
 for(const auto&[ids,s]:unique){SCRow row(225);auto add=[&](int id,int sign){const auto&p=points.at(size_t(id));int col=p.at("index").integer(),weight=p.at("sign").integer();require(col>=-1&&col<225&&(col<0?weight==0:weight==1||weight==-1),"unchanged signed columns");if(col>=0)row[size_t(col)]+=sign*weight;};for(int id:ids)add(id,1);for(const auto&id:ref)add(id.integer(),-1);for(size_t j=0;j<225;++j)require(sc_reduce(row[j])==sc_reduce(SCBig(s.at("row").arr[j].scalar)),"independently reconstructed signed row");require(group.valid(row),"independent named-group row sum");SCRow altered=row;altered[0]+=1;require(!group.valid(altered),"changed coefficient rejected by group");closed.push_back(row);row.resize(429);full.push_back(std::move(row));sections.push_back(s);}
 auto basis=abasis(closed);size_t rank=sc_rank(closed),total=sc_rank(full);require(rank==basis.size()&&total==rank+nrank&&rank<=224,"complete old-only and auxiliary-eliminated ranks agree");if(old_mode)require(n==226&&unique.size()==7&&rank==6,"old-pool exact qualification");
 std::cout<<"{\"scope\":\"complete-old-base-closure-audit\",\"old_mode\":"<<(old_mode?"true":"false")<<",\"pool_size\":"<<n<<",\"sections\":"<<sections.size()<<",\"all_line_attempts\":"<<attempted<<",\"old_columns\":225,\"baseline_rank\":6,\"full_rank\":"<<total<<",\"auxiliary_rank\":"<<nrank<<",\"closed_rank\":"<<rank<<",\"candidate_gain\":"<<rank-6<<",\"independent_elliptic_rows_checked\":"<<sections.size()<<",\"basis_source_indices\":[";for(size_t i=0;i<basis.size();++i)std::cout<<(i?",":"")<<basis[i];std::cout<<"],\"independent_new_sections\":[";bool comma=false;for(auto i:basis)if(i>=6){if(comma)std::cout<<',';std::cout<<i-6;comma=true;}std::cout<<"],\"positive_gain_established\":false,\"actual_KM_followup_required_if_positive\":true,\"standing\":\"producer-unverified; named-group and rank verification completed\"}\n";
}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
